835	def batch_update_clients(database, payload):
836	    """执行批量修改，返回 {"updated_count": 去重后的客户数}；非法请求抛 BatchUpdateError。
837	
838	    任一问题都整次拒绝，不写入任何客户。
839	    """
840	    if not isinstance(payload, dict):
841	        raise BatchUpdateError("请求体必须是 JSON 对象")
842	
843	    raw_ids = payload.get("ids")
844	    if not isinstance(raw_ids, list):
845	        raise BatchUpdateError("ids 必须是客户编号数组")
846	    if not raw_ids:
847	        raise BatchUpdateError("未选择客户：请先勾选至少一名客户")
848	
849	    ids = []
850	    seen_ids = set()
851	    for raw_id in raw_ids:
852	        if isinstance(raw_id, bool) or not isinstance(raw_id, int) or raw_id <= 0:
853	            raise BatchUpdateError("客户编号必须是正整数：%r 不合法" % (raw_id,))
854	        if raw_id > MAX_CLIENT_ID:
855	            raise BatchUpdateError(
856	                "客户编号超出可接受范围：%d（编号须在 1 到 %d 之间）"
857	                % (raw_id, MAX_CLIENT_ID))
858	        if raw_id not in seen_ids:
859	            seen_ids.add(raw_id)
860	            ids.append(raw_id)
861	
862	    raw_updates = payload.get("updates", {})
863	    if not isinstance(raw_updates, dict):
864	        raise BatchUpdateError("updates 必须是字段修改说明对象")
865	    extra = [key for key in raw_updates if key not in OPTIONAL_FIELDS]
866	    if extra:
867	        raise BatchUpdateError("包含不能修改或不存在的字段：%s" % "、".join(extra))
868	
869	    actions = {}
870	    for field_name in OPTIONAL_FIELDS:
871	        spec = raw_updates.get(field_name, {"op": "keep"})
872	        if not isinstance(spec, dict):
873	            raise BatchUpdateError("%s的修改说明必须是对象" % FIELD_LABELS[field_name])
874	        op = spec.get("op")
875	        if op not in ("keep", "set", "clear"):
876	            raise BatchUpdateError(
877	                "%s的操作必须是 keep、set 或 clear 之一" % FIELD_LABELS[field_name])
878	        if op == "keep":
879	            continue
880	        if op == "clear":
881	            actions[field_name] = None
882	        else:
883	            actions[field_name] = _normalize_set_value(field_name, spec.get("value"))
884	
885	    if not actions:
886	        raise BatchUpdateError("全部字段均保持原值：请至少选择一个字段进行设置或清空")
887	
888	    # 一次选择的客户数可能超过 SQLite 单条语句的参数上限，存在性检查与 UPDATE
889	    # 都按参数上限分块；UPDATE 的多个分块在同一事务内一次提交，整笔修改要么
890	    # 全部生效要么全部不生效，不会因分块变成多次部分修改。
891	    variable_limit = sql_variable_limit(database)
892	
893	    existing = set()
894	    for id_chunk in _chunked(ids, variable_limit):
895	        placeholders = ",".join("?" for _ in id_chunk)
896	        existing.update(
897	            row[0]
898	            for row in database.execute(
899	                "SELECT id FROM clients WHERE id IN (%s)" % placeholders, id_chunk
900	            )
901	        )
902	    missing = [cid for cid in ids if cid not in existing]
903	    if missing:
904	        raise BatchUpdateError("找不到对应客户，编号：%s" % "、".join(str(c) for c in missing))
905	
906	    # 每条 UPDATE 还要为每个修改字段绑定一个赋值参数，编号分块需相应留出位置。
907	    id_chunk_size = max(1, variable_limit - len(actions))
908	    assignments = ", ".join("%s = ?" % field_name for field_name in actions)
909	    values = list(actions.values())
910	    try:
911	        for id_chunk in _chunked(ids, id_chunk_size):
912	            placeholders = ",".join("?" for _ in id_chunk)
913	            database.execute(
914	                "UPDATE clients SET %s WHERE id IN (%s)" % (assignments, placeholders),
915	                values + id_chunk,
916	            )
917	        database.commit()
918	    except sqlite3.DatabaseError:
919	        database.rollback()
920	        raise BatchUpdateError("保存失败：数据库错误，本次修改未生效")
921	
922	    return {"updated_count": len(ids)}
