1064	    date_index = index.get("important_date")
1065	
1066	    existing = {}
1067	    for cid, cname in database.execute("SELECT id, name FROM clients"):
1068	        existing[(cname or "").strip().casefold()] = cid
1069	
1070	    imported = []
1071	    failures = []
1072	    seen_in_file = {}
1073	
1074	    for row_number, raw in enumerate(data_rows, start=1):
1075	        if len(raw) != len(headers):
1076	            failures.append({
1077	                "row": row_number,
1078	                "reason": "列数不符：表头有 %d 列，该记录有 %d 列" % (len(headers), len(raw)),
1079	            })
1080	            continue
1081	
1082	        name = raw[name_index].strip()
1083	        problems = []
1084	        if not name:
