415	// 测试流程
416	// ---------------------------------------------------------------------------
417	async function run() {
418	  const browser = await puppeteer.launch({
419	    executablePath: process.env.CHROME || "/usr/bin/google-chrome",
420	    headless: true,
421	    args: ["--no-sandbox", "--disable-dev-shm-usage"],
422	  });
423	
424	  const servers = [];
425	  try {
426	    // ===================================================================
427	    // 场景 A：正常导入并成功刷新列表
428	    // ===================================================================
429	    {
430	      const server = await startServer("normal");
431	      servers.push(server);
432	      const {base} = server;
433	      const seeded = await seed(base, ["已有客户"]);
434	
435	      const session = await openSession(browser, base);
436	      const {page} = session;
437	      const init = await importSnap(page);
438	      check("A 初始：列表显示一名已有客户、无报告、导入按钮可用",
439	        init.rows.length === 1 && !init.reportVisible && !init.submitDisabled &&
440	        init.fileCount === 0, init.rows);
441	
442	      const csv = buildCsv(
